from dataclasses import dataclass
import numpy as np


@dataclass(frozen=True)
class SequenceMetrics:
    token_count: np.ndarray
    sum_logprob: np.ndarray
    mean_nll: np.ndarray
    perplexity: np.ndarray


def masked_sequence_metrics(
    selected_logprobs: np.ndarray,
    mask: np.ndarray,
) -> SequenceMetrics:
    logprobs = np.asarray(selected_logprobs, dtype=np.float64)
    active = np.asarray(mask, dtype=bool)
    if logprobs.shape != active.shape:
        raise ValueError("selected_logprobs and mask must have the same shape")
    if logprobs.ndim == 1:
        logprobs = logprobs[None, :]
        active = active[None, :]
    elif logprobs.ndim != 2:
        raise ValueError("expected shape [B, T] or [T]")
    if np.any(~np.isfinite(logprobs[active])):
        raise ValueError("active log-probabilities must be finite")

    token_count = active.sum(axis=1).astype(np.int64)
    if np.any(token_count == 0):
        raise ValueError("empty sequence mask")
    sum_logprob = np.where(active, logprobs, 0.0).sum(axis=1)
    mean_nll = -sum_logprob / token_count
    return SequenceMetrics(
        token_count=token_count,
        sum_logprob=sum_logprob,
        mean_nll=mean_nll,
        perplexity=np.exp(mean_nll),
    )
```

